async function languageSnapshot(page){const found=await page.evaluate(()=>{const root=document.querySelector('.notework-root');if(!root)return[];const chunks=[root.textContent,...Array.from(root.querySelectorAll('[aria-label],[title],[placeholder]'),x=>[x.getAttribute('aria-label'),x.getAttribute('title'),x.getAttribute('placeholder')].filter(Boolean).join(' '))];return chunks.filter(x=>/[\uAC00-\uD7A3]/u.test(x)).map(x=>x.slice(0,800));});report.languageSnapshots++;for(const text of found)if(!report.languageViolations.includes(text))report.languageViolations.push(text);}
