  const engine=new KnowledgeEngine({vault,getTags:file=>tagRecords.get(file.path)||[],embeddingProvider});const mobileEngine=new KnowledgeEngine({vault:{...vault,adapter:{...vault.adapter,getBasePath:()=> 'synthetic-phone-vault'}},getTags:file=>tagRecords.get(file.path)||[],embeddingProvider});const archive=new ConversationArchive({vault,idFactory:()=> 'synthetic-conversation-'+(++archiveSequence),clock:()=>new Date('2026-10-06T09:00:00.000Z')});
  report.limitations.push('KnowledgeEngine and ConversationArchive run unchanged in Node via a Playwright binding, with a synthetic vault and synthetic embedding/analysis responses; this validates UI/controller integration rather than real Obsidian/cloud performance.');
